// scene/inventory-word-lists.mjs — THE INVENTORY OF FIXED WORD LISTS in the Republic-reading scripts, generated by grep, re-runnable.  (2026-10-14)
//
//   node eval/the-fold/scene/inventory-word-lists.mjs            print the table
//   node eval/the-fold/scene/inventory-word-lists.mjs --write    rewrite the marked block in NO-FIXED-LISTS-SCENE.md
//
// A finding is a literal enumeration of natural-language words that decides behaviour: a Set/array of three or more word strings, or a
// regex literal / pattern string with an alternation of three or more words. Not counted: all-caps tags (UD, operator names), tokens
// with a hyphen, dot or digit (layer names, file names), numbers. The DETECTION is mechanical; the VERDICT column is looked up in
// VERDICTS below, keyed by "<script>:<name>" — a finding with no entry prints UNREVIEWED, so a new list cannot pass silently.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const SCRIPTS = ["holograph-minds", "foucault-sublation", "collision-reading", "historicity-lane", "one-log", "export-turns", "export-speaker-frames", "export-speaker-frames-v2", "line-or-circle", "frames-bridge", "experience-reading", "minds-reading", "republic-parallel-concepts", "concept-bridge", "read-greek"];

const isWord = (w) => /^[\p{L}'’]{2,}$/u.test(w) && !/^[A-Z0-9_]+$/.test(w);
const strings = (s) => [...s.matchAll(/"([^"\\]*)"|'([^'\\]*)'/g)].map((m) => m[1] ?? m[2]);
function findings(file) {
  const src = fs.readFileSync(path.join(HERE, file + ".mjs"), "utf8").split("\n"), out = [];
  src.forEach((line, i) => {
    const code = line.replace(/\/\/.*$/, "");
    const name = (/(?:const|let)\s+([A-Za-z_$][\w$]*)\s*=/.exec(code) ?? /\b([A-Za-z_$][\w$]*)\s*:/.exec(code))?.[1] ?? "(inline)";
    // Set / array literals of strings
    for (const m of code.matchAll(/(?:new Set\()?\[((?:\s*(?:"[^"]*"|'[^']*')\s*,?)+)\]/g)) {
      const ws = strings(m[1]); const words = ws.filter(isWord);
      if (words.length >= 3 && words.length >= ws.length * 0.6) out.push({ file, line: i + 1, name, kind: "set/array", n: words.length, sample: words.slice(0, 6).join(" ") });
    }
    // a gazetteer: a regex of rigid names mapped to background files
    if (/\bre:\s*\//.test(code) && /\bfiles:\s*\[/.test(code)) out.push({ file, line: i + 1, name: "ANCHORS", kind: "gazetteer", n: strings(code.slice(code.indexOf("files:"))).length, sample: (/name:\s*"([^"]+)"/.exec(code) ?? [])[1] ?? "" });
    // a split-string constant of words
    for (const m of code.matchAll(/new Set\("([^"]{15,})"\.split\(/g)) { const words = m[1].split(/\s+/).filter(isWord); if (words.length >= 3) out.push({ file, line: i + 1, name, kind: "split-string", n: words.length, sample: words.slice(0, 6).join(" ") }); }
    // regex literals and pattern strings with an alternation of words
    for (const m of code.matchAll(/\(\?:([^()]*\|[^()]*)\)|\(([^()]*\|[^()]*)\)|"((?:[a-z]+(?: [a-z]+)?\|){3,}[a-z]+(?: [a-z]+)?)"/g)) {
      const alts = (m[1] ?? m[2] ?? m[3]).split("|").map((a) => a.replace(/\\[bwsd][+*?]?|[?+*\\^$]|\(\?:|\)/g, "").replace(/'\u2019/g, "'").trim()).filter(Boolean);
      const words = alts.filter((a) => /^[\p{L}' ]{2,}$/u.test(a) && !/^[A-Z0-9_ ]+$/.test(a));
      if (words.length >= 3 && words.length >= alts.length * 0.6) out.push({ file, line: i + 1, name, kind: "alternation", n: words.length, sample: words.slice(0, 6).join(" ") });
    }
  });
  return out;
}

// ── the verdicts: declared annotations, keyed by script:name ────────────────────────────────────────────────────────────────────────────
const SAME = {   // the same list is typed in three scripts
  MODALS: "LEFT — the parser types 'modal' (AUX, VerbForm=Fin only), not 'deontic': deriving it adds can/may/will/would/could/might; VerbNet does not type must/ought/shall/should.",
  OBEY: "LEFT — VerbNet has no obey/heed class; follow/serve/mind are contested across unrelated classes.",
  COMMAND: "LEFT — VerbNet sections 58/59.1/63/64/103 type most of it (order, urge, compel, enforce, allow/forbid, require) but lose bid/make/direct/instruct/tell and add beg/urge; the section choice is itself a declared list. Not measured to leave the numbers alone.",
  NONDEONTIC: "LEFT — EVA/SIG typing would also catch 'be' (SIG, unanimous in the act prior) and so drop 'must be'.",
  LIGHT: "LEFT — no derivation checked against it; polysemy by VerbNet class count needs a hand-set threshold.",
  STOPHEAD: "LEFT — closed-class UPOS covers it/that/this/which/what/there; 'thing(s)', 'way', 'one' are NOUN/NUM and would stay.",
  NEGW: "REPLACED — parser lexicon Polarity=Neg / PronType=Neg (see report).",
  NEG: "REPLACED — parser lexicon Polarity=Neg / PronType=Neg (see report).",
  SLAVE: "REPORT — derived by Stephanus alignment (servants/masters drop out; numbers move); the user chooses. Not wired.",
  RULE: "REPORT — derived by Stephanus alignment; numbers move; the user chooses. Not wired.",
  SENT_CUE: "LEFT — the union of MODALS/OBEY/COMMAND; follows them.",
  CUE: "LEFT — the union of MODALS/OBEY/COMMAND; follows them.",
  RULED: "NOT A WORD LIST — corpus layer ids (file names).",
};
export const VERDICTS = {
  "holograph-minds:MODALS": SAME.MODALS, "holograph-minds:OBEY": SAME.OBEY, "holograph-minds:COMMAND": SAME.COMMAND, "holograph-minds:NONDEONTIC": SAME.NONDEONTIC, "holograph-minds:STOPHEAD": SAME.STOPHEAD, "holograph-minds:LIGHT": SAME.LIGHT,
  "holograph-minds:NEGW": SAME.NEGW, "holograph-minds:SLAVE": SAME.SLAVE, "holograph-minds:RULE": SAME.RULE, "holograph-minds:sentOf": SAME.SENT_CUE, "holograph-minds:CUE": SAME.CUE, "holograph-minds:RULED": SAME.RULED,
  "foucault-sublation:MODALS": SAME.MODALS, "foucault-sublation:OBEY": SAME.OBEY, "foucault-sublation:COMMAND": SAME.COMMAND, "foucault-sublation:NONDEONTIC": SAME.NONDEONTIC, "foucault-sublation:STOPHEAD": SAME.STOPHEAD, "foucault-sublation:LIGHT": SAME.LIGHT,
  "foucault-sublation:NEGW": SAME.NEGW, "foucault-sublation:SLAVE": SAME.SLAVE, "foucault-sublation:RULE": SAME.RULE, "foucault-sublation:sentOf": SAME.SENT_CUE, "foucault-sublation:CUE": SAME.CUE, "foucault-sublation:RULED": SAME.RULED,
  "line-or-circle:MODALS": SAME.MODALS, "line-or-circle:OBEY": SAME.OBEY, "line-or-circle:COMMAND": SAME.COMMAND, "line-or-circle:NONDEONTIC": SAME.NONDEONTIC, "line-or-circle:STOPHEAD": SAME.STOPHEAD, "line-or-circle:LIGHT": SAME.LIGHT,
  "line-or-circle:NEGW": SAME.NEGW, "line-or-circle:SLAVE": SAME.SLAVE, "line-or-circle:RULE": SAME.RULE, "line-or-circle:sentOf": SAME.SENT_CUE, "line-or-circle:CUE": SAME.CUE, "line-or-circle:RULED": SAME.RULED,
  "experience-reading:SLAVE": SAME.SLAVE, "experience-reading:RULE": SAME.RULE, "experience-reading:RULED": SAME.RULED, "minds-reading:SLAVE": SAME.SLAVE, "minds-reading:RULE": SAME.RULE, "minds-reading:RULED": SAME.RULED,
  "collision-reading:SLAVE_L": "REPORT — derived slave lemma set = {slave}; servant/bondman/bondsman drop out (variants in the report). Not wired.",
  "collision-reading:GROUP_L": "LEFT — no resource types person-nouns ('other groups'); the comparison class is the script's own question.",
  "collision-reading:RULEWORD": "REPORT — derived rule words plus the deontic words (must/ought/shall/obey stay declared with MODALS). Not wired.",
  "collision-reading:SLAVEWORD": "REPORT — derived slave words. Not wired.",
  "collision-reading:hasSet": "LEFT — prefilter for SLAVE_L ∪ GROUP_L; follows GROUP_L.",
  "historicity-lane:STEMS": "PARTIAL — δουλ and ελευθερ derived from the grid's pins by successor variety (output identical); ανδραποδ, οικετ, θεραπον declared (not derivable without pulling in the tyrant and master stems).",
  "one-log:ANCHORS": "LEFT — a gazetteer from rigid names to background files; no resource pairs a Republic name with a Wikipedia file, and title-matching loses Cephalus→metic, Sparta→helots.",
  "holograph-minds:neg": "LEFT — the prohibitive reading of forbid/forbade/forbidden (a lemma test); follows COMMAND.", "foucault-sublation:neg": "LEFT — follows COMMAND (forbid).", "line-or-circle:neg": "LEFT — follows COMMAND (forbid).",
  "collision-reading:(inline)": "NOT A WORD LIST — names of three measures.", "frames-bridge:COORDS": "NOT A WORD LIST — field names of the pattern record.",
  "export-turns:tier": "LEFT — he/she/they as the tier-3 tag pronoun: derivable (lexicon PRON Person=3 Case=Nom) but tied to V, which is left; not measured against 45/472/721.",
  "export-speaker-frames-v2:bytes": "LEFT — be/is/are/was/were copula forms: derivable from the parser lemma (cop deprel) but not measured against the speaker-frame counts.",
  "export-speaker-frames-v2:pm": "LEFT — same header-word exclusion as export-turns CAST.",
  "one-log:body": "LEFT — first slave-word sentence of a section; follows SLAVE (report).",
  "one-log:sm": "LEFT — first slave-word sentence of a section; follows SLAVE (report).",
  "one-log:STATUS": "LEFT — status words scoring background spans; the grid pins only master/ruler/law/tyrant/freedom/slavery of them (metic, helot, citizen, oligarch, barbarian are not in it).",
  "one-log:sm": "LEFT — first slave-word sentence of a section; follows SLAVE (report).",
  "export-turns:V": "LEFT — VerbNet section 37 (communication) loses 'answered', the commonest Jowett speech tag (answer is CON in the act prior); the numbers would move.",
  "export-turns:CAST": "LEFT — header words excluded from the cast; a capitalised-in-majority test is derivable but was not measured against the 45/472/721 table.",
  "export-speaker-frames-v2:NAMED": "LEFT — same header-word exclusion as export-turns CAST.",
  "republic-parallel-concepts:STOP_E": "LEFT — page frequency (the script's own 25% cap) covers the function words, but removing the list changes which pins are born, and the prior it writes is a shared artifact (Zenodotus) that was not regenerated.",
};

export function inventory() {
  const rows = SCRIPTS.flatMap(findings);
  return rows.map((r) => ({ ...r, verdict: VERDICTS[`${r.file}:${r.name}`] ?? "UNREVIEWED" }));
}
export function table(rows = inventory()) {
  const esc = (s) => String(s).replace(/\|/g, "\\|");
  return ["| script:line | name | kind | words | sample | verdict |", "|---|---|---|---|---|---|", ...rows.map((r) => `| ${r.file}:${r.line} | ${esc(r.name)} | ${r.kind} | ${r.n} | ${esc(r.sample)} | ${esc(r.verdict)} |`)].join("\n");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const rows = inventory(); const md = table(rows);
  const unreviewed = rows.filter((r) => r.verdict === "UNREVIEWED");
  if (process.argv.includes("--write")) {
    const f = path.join(HERE, "NO-FIXED-LISTS-SCENE.md"); const s = fs.readFileSync(f, "utf8");
    const a = "<!-- inventory:begin -->", b = "<!-- inventory:end -->"; const i = s.indexOf(a), j = s.indexOf(b);
    if (i < 0 || j < 0) { console.error("markers missing"); process.exit(1); }
    fs.writeFileSync(f, s.slice(0, i + a.length) + "\n" + md + "\n" + s.slice(j));
    console.log(`wrote ${rows.length} findings → ${f}`);
  } else console.log(md);
  console.log(`\n${rows.length} findings · ${unreviewed.length} UNREVIEWED`);
  for (const r of unreviewed) console.log(`  UNREVIEWED ${r.file}:${r.line} ${r.name} (${r.sample})`);
}
